class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        MAX = 100000
        first = {}
        for j, e in enumerate(elements):
            if e not in first:
                first[e] = j
        # best index for each value v
        best = [-1] * (MAX + 1)
        # process distinct element values in order of their first index
        for e, idx in sorted(first.items(), key=lambda x: x[1]):
            for m in range(e, MAX + 1, e):
                if best[m] == -1:
                    best[m] = idx
        return [best[g] for g in groups]
