import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    m = draw(st.integers(1, 6))
    k = draw(st.integers(1, 6))
    vals = st.one_of(st.integers(1, 12), st.sampled_from([1, 2, 3, 6, 12, 100000]))
    groups = draw(st.lists(vals, min_size=m, max_size=m))
    elements = draw(st.lists(vals, min_size=k, max_size=k))
    if draw(st.booleans()):
        groups = sorted(groups)
    if draw(st.booleans()):
        elements = sorted(elements, reverse=True)
    return f"{json.dumps(groups)}\n{json.dumps(elements)}\n"

def validate(inp):
    lines = inp.split("\n")
    if len(lines) < 2:
        return False
    if lines[2:] and any(l.strip() for l in lines[2:]):
        return False
    try:
        groups = json.loads(lines[0])
        elements = json.loads(lines[1])
    except Exception:
        return False
    if not isinstance(groups, list) or not isinstance(elements, list):
        return False
    if not (1 <= len(groups) <= 10**5) or not (1 <= len(elements) <= 10**5):
        return False
    for x in groups + elements:
        if type(x) is not int:
            return False
    if not all(1 <= g <= 10**5 for g in groups):
        return False
    if not all(1 <= e <= 10**5 for e in elements):
        return False
    return True

def ref(inp):
    lines = inp.split("\n")
    groups = json.loads(lines[0])
    elements = json.loads(lines[1])
    res = []
    for g in groups:
        ans = -1
        for j, e in enumerate(elements):
            if g % e == 0:
                ans = j
                break
        res.append(ans)
    return json.dumps(res)
