import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    m = draw(st.integers(1, 6))
    k = draw(st.integers(1, 6))
    mode = draw(st.integers(0, 3))
    if mode == 0:
        # small values, lots of collisions
        groups = draw(st.lists(st.integers(1, 12), min_size=m, max_size=m))
        elements = draw(st.lists(st.integers(1, 12), min_size=k, max_size=k))
    elif mode == 1:
        # all equal values
        v = draw(st.integers(1, 20))
        groups = [v] * m
        elements = [draw(st.sampled_from([1, v, 2, 3])) for _ in range(k)]
    elif mode == 2:
        # extremes: 1s and maximal-scaled values
        groups = draw(st.lists(st.sampled_from([1, 2, 20, 19, 16]), min_size=m, max_size=m))
        elements = draw(st.lists(st.sampled_from([1, 2, 3, 4, 5, 20]), min_size=k, max_size=k))
    else:
        # sorted / reverse-sorted groups
        groups = sorted(draw(st.lists(st.integers(1, 30), min_size=m, max_size=m)))
        if draw(st.booleans()):
            groups = groups[::-1]
        elements = draw(st.lists(st.integers(1, 30), min_size=k, max_size=k))
    return f"{json.dumps(groups)}\n{json.dumps(elements)}"

